import { Value } from "@sinclair/typebox/value";
import yaml from "js-yaml";
import { configReadSchema, configSchemaValidator, pluginNameRegex, urlRegex, configSchema } from "../config/plugin-schema";
export function parseConfig(yamlContent, logger) {
    try {
        Value.Cast(configReadSchema, yaml.load(yamlContent)); // Validate schema
        return parsePluginLocations(yamlContent, logger);
    }
    catch (error) {
        logger.warn("Failed to parse YAML content", { stack: error instanceof Error ? error.stack : String(error) });
        return [];
    }
}
export function validateYamlContent(content, logger) {
    try {
        const { yaml, errors } = parseYaml(content, logger);
        if (errors) {
            return { isValid: false, error: errors.map((error) => error.message).join(", ") };
        }
        const targetRepoConfiguration = yaml;
        if (targetRepoConfiguration) {
            const configSchemaWithDefaults = Value.Default(configSchema, targetRepoConfiguration);
            const errors = configSchemaValidator.testReturningErrors(configSchemaWithDefaults);
            if (errors) {
                return {
                    isValid: false,
                    error: Array.from(errors)
                        .map((error) => error.message)
                        .join(", "),
                };
            }
        }
        return { isValid: true };
    }
    catch (error) {
        return {
            isValid: false,
            error: error instanceof Error ? error.message : "Invalid YAML content",
        };
    }
}
export function parseYaml(data, logger) {
    if (!data) {
        return { yaml: null, errors: null };
    }
    try {
        const parsedData = yaml.load(data);
        return { yaml: parsedData ?? null, errors: null };
    }
    catch (error) {
        logger.warn("Error parsing YAML", { stack: error instanceof Error ? error.stack : String(error) });
        return { errors: [error], yaml: null };
    }
}
export function parsePluginIdentifier(value) {
    if (urlRegex.test(value)) {
        return value;
    }
    const matches = RegExp(pluginNameRegex).exec(value);
    if (!matches) {
        throw new Error(`Invalid plugin name: ${value}`);
    }
    return {
        owner: matches[1],
        repo: matches[2],
        ref: matches[4] || undefined,
    };
}
export function parsePluginLocations(yamlContent, logger) {
    const { yaml: parsedYaml, errors } = parseYaml(yamlContent, logger);
    if (errors) {
        logger.warn("Failed to parse YAML content:" + errors.map((error) => error.message).join(", "));
        return [];
    }
    const plugins = parsedYaml?.plugins || [];
    return Object.keys(plugins).flatMap((key) => {
        return parsePluginIdentifier(key);
    });
}
